#[using="Type"] Lemma base_range_sound : forall segs E M kn e lo hi,
  know_ok segs E M kn -> base_range kn e = Some (lo, hi) ->
  (lo <= bv_unsigned (edenot E e))%Z /\ (bv_unsigned (edenot E e) <= hi)%Z.
Proof.
ltac2:(KReplay.run1 (kr_t_SymExec2Sound ()) ["FPX_2"] "h01Eh11Hh23Hknh31Mh41eh52hih62knh72loh84segsp;1p;4p;2p;3p;9g01?[j11Tg00hcj10Tg00iHj12Tg00ifj13Tg037\j14Tg07_;j4;Tg01W:j2:Tg0:57j28Tg025mj47Tg03>Hj26Tg009cj35Tg0:6Il99Tg05X^#1g00jog00l<#0#0#0R0#0#0#0#2#3%20#3#4[g07Z=#1g00aPg00c=R0f6R1f5R2f4R3f3R4C;1:00R5#41834P0P0f2R6f1R7C7,6535f8f7P1P2P3P4P6P7f0M99W1W2X50W7W4W6W3W0W8o"). Qed.

#[using="Type"] Lemma sub_itv_sound : forall E b k n c m,
  sub_itv b k n c m = true ->
