#[using="Type"] Lemma know_lookup_acc : forall segs kn rb rk n sx hints acc,
  match know_lookup segs kn rb rk n sx hints acc with
  | LHit _ scs _ | LMiss scs _ => exists pre, scs = pre ++ acc
  | LStuck => True
  end.
Proof.
